SELECT COUNT(*)
  FROM TB_AM11M01 M
 WHERE M.DOC_STATUS IN ('REQUEST', 'PROGRESS')
   AND (
        M.CURR_APPROVER_ID = #{userId}
        OR EXISTS (
            SELECT 1 FROM TB_AM11D01 P
             WHERE P.DOC_ID = M.DOC_ID
               AND P.LINE_STATUS = 'PENDING'
               AND P.APPROVER_ID = #{userId}
        )
        OR EXISTS (
            SELECT 1
              FROM TB_AM03M02 G
             WHERE G.ORIGIN_USER_ID = M.CURR_APPROVER_ID
               AND G.DELEGATE_USER_ID = #{userId}
               AND G.USE_YN = 'Y'
               AND TO_CHAR(SYSDATE, 'YYYYMMDD') BETWEEN G.START_DT AND G.END_DT
        )
   )

SELECT COUNT(*)
  FROM TB_AM11M01 M
 WHERE M.DOC_STATUS IN ('REQUEST', 'PROGRESS')
   AND (
        M.DRA_USER_ID = #{userId}
        OR EXISTS (
            SELECT 1
              FROM TB_AM11D01 D
             WHERE D.DOC_ID = M.DOC_ID
               AND D.APPROVER_ID = #{userId}
        )
   )

SELECT COUNT(*)
  FROM TB_AM11M01 M
 WHERE M.DOC_STATUS = 'COMPLETED'
   AND (
        M.DRA_USER_ID = #{userId}
        OR EXISTS (
            SELECT 1
              FROM TB_AM11D01 D
             WHERE D.DOC_ID = M.DOC_ID
               AND D.APPROVER_ID = #{userId}
        )
   )

SELECT COUNT(*)
  FROM TB_AM11M01 M
 WHERE M.DOC_STATUS = 'REJECTED'
   AND (
        M.DRA_USER_ID = #{userId}
        OR EXISTS (
            SELECT 1
              FROM TB_AM11D01 D
             WHERE D.DOC_ID = M.DOC_ID
               AND D.APPROVER_ID = #{userId}
        )
   )
